import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        int s = in.nextInt() - 1;
        long t = in.nextLong();

        while (t % n != 0) {
            s = (s < m) ? (int)((s + t) % n) : (int)((s - t) % n);
            if (s < 0) s += n;
            t--;
        }
        t /= n;

        int[] seen = new int[n];
        Arrays.fill(seen, -1);
        seen[s] = 0;
        int count = 0;
        while (t-- > 0) {
            count++;
            for (int i = n - 1; i >= 1; i--) {
                s = (s < m) ? (s + i) % n : (s - i + n) % n;
            }
            if (seen[s] != -1) {
                t %= (count - seen[s]);
            }
            seen[s] = count;
        }
        System.out.println(s + 1);
    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1 << 16];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            long res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
